        if bb[mid][1] != exp_out: bad.append(("maxOutput", mid, bb[mid][1], exp_out))
        exp_in = (e["effective_input_ceiling"] - 20000) if isinstance(e.get("effective_input_ceiling"), int) else e.get("context_window")
        if bb[mid][0] != exp_in: bad.append(("maxInput", mid, bb[mid][0], exp_in))
        exp_r = ((e.get("params") or {}).get("thinking_adaptive") is True) or ("thinking_traces" in (e.get("capabilities") or []))
        if reasoning.get(mid) != ("true" if exp_r else "false"): bad.append(("reasoning", mid, reasoning.get(mid), exp_r))
print("entries:", sum(len(pv.get("models") or {}) for pv in cat["providers"].values()), "mismatches:", bad or "none")
